/**
* MK Auto Elite - service booking form.
* Submits [data-mkae-booking] forms to the mkae_submit_booking AJAX endpoint.
* Dependency-free; reads config from window.MKAE (ajaxUrl, nonce).
*/
(function () {
'use strict';
function cfg() {
return window.MKAE || {};
}
function setStatus(el, msg, kind) {
if (!el) {
return;
}
el.textContent = msg;
el.className = 'mkae-booking__status' + (kind ? ' is-' + kind : '');
}
function submit(form) {
var statusEl = form.querySelector('[data-mkae-booking-status]');
var button = form.querySelector('[data-mkae-booking-submit]');
var name = (form.querySelector('[name="mkae_name"]') || {}).value || '';
var phone = (form.querySelector('[name="mkae_phone"]') || {}).value || '';
var service = (form.querySelector('[name="mkae_service"]') || {}).value || '';
if (!name.trim() || !phone.trim() || !service.trim()) {
setStatus(statusEl, 'Please fill in your name, phone and the service needed.', 'error');
return;
}
var data = new FormData(form);
data.append('action', 'mkae_submit_booking');
data.append('nonce', cfg().nonce || '');
if (button) {
button.disabled = true;
}
setStatus(statusEl, 'Sending your request...', 'pending');
fetch(cfg().ajaxUrl, {
method: 'POST',
credentials: 'same-origin',
body: data
})
.then(function (r) {
return r.json();
})
.then(function (res) {
if (res && res.success) {
var msg = (res.data && res.data.message) || 'Thank you. We have received your booking and will confirm shortly.';
setStatus(statusEl, msg, 'ok');
form.reset();
} else {
var err = (res && res.data && res.data.message) || 'Sorry, something went wrong. Please try again or WhatsApp us.';
setStatus(statusEl, err, 'error');
}
})
.catch(function () {
setStatus(statusEl, 'Network error. Please try again or WhatsApp us.', 'error');
})
.then(function () {
if (button) {
button.disabled = false;
}
});
}
function init() {
var forms = document.querySelectorAll('[data-mkae-booking]');
for (var i = 0; i < forms.length; i++) {
(function (form) {
form.addEventListener('submit', function (e) {
e.preventDefault();
submit(form);
});
})(forms[i]);
}
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', init);
} else {
init();
}
})();